if defined?(BS2Modules::Effects) && BS2Suite.enabled?('reference_cards')
module BS2Modules::Effects
  class << self
    alias bs2098_verified_sources sources
    def sources(actor)
      rows=bs2098_verified_sources(actor)
      rows.each do |row|
        object=row[:object]
        next unless object.is_a?(RPG::EquipItem)
        next unless object && BS2Suite::Reference098.get(object)
        card=BS2QoL::PracticalCard.new(object,actor,:en)
        row[:details]=card.section_names.zip(card.sections).reject { |label,lines| label=='Weapon shelves' }.map { |label,lines| lines }.flatten
      end
      rows
    end
    alias bs2098_verified_active active
    def active(actor)
      return bs2098_verified_active(actor)
      rows.each do |row|
        next unless row[:kind]==:state
        state=$data_states[row[:id]];next unless state && BS2Suite::Reference098.get(state)
        db=BS2Suite::Reference098
        row[:details]=duration(actor,state)+db.facts(state).select { |a,b| a=='Actions' }.map { |a,b| b }+db.lines(state,'Properties')+db.lines(state,'Special')
      end
      rows
    end
  end
end
end
if BS2Suite.enabled?('reference_cards')
class BS2QoL::PracticalCard
  alias bs2098_reference_title title
  def title
    value=bs2098_reference_title
    row=BS2Suite::Reference098.get(@object)
    value.to_s.empty? ? @object.class.to_s.sub('RPG::','')+' #'+@object.id.to_s : value
  end
  alias bs2098_card_initialize initialize
  def initialize(object,actor=nil,language=:en)
    bs2098_card_initialize(object,actor,language)
    # A journal entry has an observed action ID, not a frozen combatant snapshot.
    if !actor && object.is_a?(RPG::UsableItem)
      i=@section_names.index(t('Targets','Targets'))
      if i;@section_names.delete_at(i);@sections.delete_at(i);end
    end
  end
  def reference098;BS2Suite::Reference098;end
  def ref_lines(object,title);reference098.lines(object,title);end
  def ref_facts(object);reference098.facts(object);end
  alias bs2098_old_use practical_use
  def practical_use
    return bs2098_old_use if language==:en || !reference098.get(@resolved)
    x=@resolved
    lead=ref_lines(x,'Brief')
    lead=[reference098.brief(x)] if lead.empty? && x.damage.none?
    # Keep the reviewed explanations when the compiled database supplies only
    # a short mechanical summary (field skills and conditional techniques).
    reviewed=editorial || []
    unless BS2Suite.enabled?('field_skills')
      reviewed=reviewed.reject { |line| line.include?('automatic') || line.include?('automatic') }
    end
    rows=reviewed+lead+practical_cost
    info=ref_facts(x)
    kind=info.find { |a,b| a=='Damage / element' };hit=info.find { |a,b| a=='Hit type' }
    if kind
      damage,element=kind[1].split(' · ',2)
      rows<<damage+(element ? ' · element: '+element : '')
    end
    rows<<'Hit type: '+hit[1] if hit
    info.each do |label,value|
      next unless ['Target','Use','Consumable'].include?(label)
      next if x.occasion==3 && ['Target','Consumable'].include?(label)
      rows<<label+': '+value
    end
    rows<<'Repeats per target: '+x.repeats.to_s if x.repeats>1
    rows<<'Base success: '+x.success_rate.to_s+'%; not the final target chance.' if x.success_rate!=100
    if x.is_a?(RPG::Item)
      rows<<'In inventory: '+$game_party.item_number(x).to_s if $game_party
    elsif actor
      sources=actor.equips.compact.select { |w| w.features.any? { |f| f.code==43 && f.data_id==@object.id } }
      rows<<'Granted by: '+sources.map { |w| name(w) }.join(', ') unless sources.empty?
    end
    if [0,1].include?(x.occasion)
      q=quick_info(x)
      if q
        # The database distinguishes party-wide and per-user limits.
        line=ref_lines(x,'Special').find { |s| s.start_with?('Instant,') }
        rows<<(line || 'Instant, no action slot; limit '+q[0].to_s)+(actor ? '; used '+q[1].to_s : '')
      else;rows<<'Uses a normal action.';end
    end
    prefixes=['Current restrictions:','Current variant:','Original skill selection cost:','Required weapon types (either):',
      'Current restrictions:','Current variant:','Original skill selection cost:','Required weapon types (either):']
    rows+=overview.select { |s| prefixes.any? { |p| s.start_with?(p) } }
    if @bs2095_execution_weapon
      rows<<(@bs2096_sole_source ? 'Sole technique source: ' : 'Final action weapon: ')+@bs2095_execution_weapon.name
    end
    if BS2Suite::ActionRules.gunbreak?(@object)
      rows<<BS2Suite::Keys.token(:Z)+' — automatic Gun Break when selected in Skills or V.'
    end
    rows
  end
  alias bs2098_old_effects practical_effects
  def practical_effects
    x=@resolved
    if language==:en || !reference098.get(x)
      rows=bs2098_old_effects
    else
    rows=ref_lines(x,'Effects').reject { |s| s.start_with?('Calls event:') }
    if x.effects.any? { |e| [11,12].include?(e.code) && e.value1<=0 && e.value2<=0 && (e.value1<0 || e.value2<0) }
      # Compiled RU summaries predate the signed resource-effect decoder.
      # Replace resource lines only; retain reviewed state/event explanations.
      rows.reject! { |s| s.start_with?('HP recovery:','MP recovery:') }
      resource_rows=bs2098_old_effects.select { |s| s.start_with?('HP loss:','MP loss:','HP recovery:','MP recovery:','This portion of the loss') }
      rows=resource_rows+rows
    end
    properties=ref_lines(x,'Properties')
    rows+=['Entry properties:']+properties unless properties.empty?
    # Expand states from their own verified cards; not their often inaccurate names.
    x.effects.select { |e| e.code==21 && e.data_id>0 }.each do |effect|
      state=$data_states[effect.data_id];next unless state
      rows<<name(state)+':';rows+=state_lines(state)
    end
    x.effects.select { |e| e.code==44 }.each do |effect|
      next if rows.any? { |s| s.start_with?('Souls gained:') }
      summary=event_summary(effect.data_id)
      rows<<(summary ? t(summary[0],summary[1]) : 'Special game event: outcome depends on its conditions; not numerically modeled.')
    end
    end
    if x.tp_gain!=0
      rows<<t('User gains per successful hit: TP +','User gains per successful hit: TP +')+n(x.tp_gain)+' × TCR.'
    end
    if actor
      x.effects.select { |e| e.code==43 }.each do |effect|
        skill=$data_skills[effect.data_id];next unless skill
        rows<<(actor.skill_learn?(skill) ? t('Already learned by this actor: ','Already learned by this actor: ') : t('Not yet learned by this actor: ','Not yet learned by this actor: '))+name(skill)+'.'
      end
    end
    rows
  end
  alias bs2098_old_state_lines state_lines
  def state_lines(state)
    if language==:en
      rows=bs2098_old_state_lines(state)
      if state.auto_removal_timing==3
        rows.reject! { |s| s.include?('Duration counter:') || s.include?('ATB may decrease') }
        rows.unshift('  Frame interval: '+state.turn_frame.to_s+' internal frames; '+(state.auto_remove? ? 'duration counter '+state.min_turns.to_s+'..'+state.max_turns.to_s+'.' : 'no automatic removal.'))
      end
      return rows
    end
    return bs2098_old_state_lines(state) unless reference098.get(state)
    rows=ref_facts(state).reject { |a,b| a=='After battle' }.map { |a,b| '  '+a+': '+b }
    rows+=ref_lines(state,'Properties').map { |s| '  '+s }
    rows+=ref_lines(state,'Special').map { |s| '  '+s }
    if state.auto_removal_timing>0
      rows<<'  Duration is an internal counter: ATB may decrease it before acting; this does not promise N full turns.'
    end
    rows
  end
  alias bs2098_old_formula practical_formula
  def practical_formula
    if language==:en
      rows=bs2098_old_formula
      if @resolved.damage.critical && defined?(Hi_ru_Difficulty)
        factor=Hi_ru_Difficulty::DIFFICULTY_SETTING[11][$game_variables[Hi_ru_Difficulty::VARIABLES]]
        rows<<'Current critical multiplier: ×'+n(factor)+'.'
      end
      return rows
    end
    return bs2098_old_formula unless reference098.get(@resolved)
    x=@resolved;rows=['Per hit:',x.damage.formula.to_s.strip]+ref_lines(x,'Calculation')
    used=x.damage.formula.scan(/\ba\.(atk|def|mat|mdf|mhp|mmp|hp|mp|agi|luk)\b/).flatten.uniq
    if x.damage.critical && defined?(Hi_ru_Difficulty)
      factor=Hi_ru_Difficulty::DIFFICULTY_SETTING[11][$game_variables[Hi_ru_Difficulty::VARIABLES]]
      rows.map! { |s| s.sub('critical possible; multiplier depends on difficulty setting','critical ×'+n(factor)+' now') }
    end
    rows<<'Current user: '+used.map { |key| key.upcase+' '+actor.send(key).to_s }.join(', ') if actor && !used.empty?
    rows<<'Repeats per target: '+x.repeats.to_s if x.repeats>1
    rows
  end
  alias bs2098_old_rules note_rules
  def note_rules(x)
    return bs2098_old_rules(x) unless reference098.get(x)
    rows=language==:en ? bs2098_old_rules(x) : ref_lines(x,'Special').reject { |s| s.start_with?('Instant,') }
    # The source decoder records the initial delay, while execution checks zero
    # before decrementing. State the actual check number, not N promised actions.
    if x.is_a?(RPG::UsableItem)
      rows.reject! { |s| s.start_with?('Delayed effect:') }
      x.note.scan(/<(行動後遅延発動|遅延発動)[:：]([^>]+)>/).each do |tag,value|
        parts=value.split(',').map { |v| v.to_i };linked=x.is_a?(RPG::Skill) ? $data_skills[parts[1]] : $data_items[parts[1]]
        rows<<t('Delayed: ','Delayed: ')+name(linked)+t('; check #','; check #')+(parts[2]+1).to_s+'–'+(parts[2]+(parts[3] || 0)+1).to_s+
          (tag=='行動後遅延発動' ? t(' after target actions',' after target actions') : t(' at turn end',' at turn end'))+t('; chance ','; chance ')+(parts[4] || 100).to_s+t('%. Does not trigger after target death/disappearance.','%. Does not trigger after target death/disappearance.')
      end
      if actor && x.is_a?(RPG::Skill) && /<クールタイム:(\d+)>/.match(x.note)
        rows<<t('Cooldown now: ','Cooldown now: ')+read_cooldown(x).to_s+'.'
      end
      # Do not pretend that a dormant action tag ignores PDR/MDR.
      row=reference098.get(x)
      if row[5].any? { |s| s.start_with?('PDR/MDR penetration tag') }
        rows<<t('This action does not itself ignore physical/magical damage resistance. A separate passive source can provide penetration.','This action does not itself ignore physical/magical damage resistance. A separate passive source can provide penetration.')
      end
      x.note.scan(/<使用者効果\s*(\d+)\s*>/).each do |sid|
        linked=$data_skills[sid[0].to_i];next unless linked
        effects=language==:en ? effect_lines(linked,false) : ref_lines(linked,'Effects')
        rows+=effects.map { |s| t('  On the user: ','  On the user: ')+s }
        linked.effects.select { |e| e.code==21 && e.data_id>0 }.each do |e|
          rows+=state_lines($data_states[e.data_id]) if $data_states[e.data_id]
        end
        rows<<t('  User formula: ','  User formula: ')+linked.damage.formula.to_s.strip unless linked.damage.none?
      end
      links=x.note.scan(/<使用後追加行動[:：](\d+),[^>]+>/).flatten.map { |sid| $data_skills[sid.to_i] }
      x.note.scan(/<(?:行動後遅延発動|遅延発動)[:：]([^>]+)>/).each do |value|
        sid=value[0].split(',')[1].to_i;links<<(x.is_a?(RPG::Skill) ? $data_skills[sid] : $data_items[sid])
      end
      links.compact.uniq.each do |linked|
        rows<<'  '+name(linked)+(language==:en ? '' : ': '+reference098.brief(linked).to_s)
        rows<<t('  Per hit: ','  Per hit: ')+linked.damage.formula.to_s.strip unless linked.damage.none?
      end
      rows<<t('Follow-up actions have their own conditions, cost and target. A full-chain forecast can be partial.','Follow-up actions have their own conditions, cost and target. A full-chain forecast can be partial.') unless links.compact.empty?
      if x.note.include?('<ステート変化:')
        rows<<t('When several variants apply, the last matching note tag wins.','When several variants apply, the last matching note tag wins.')
      end
    end
    rows
  end
  alias bs2098_old_equipment equipment_card
  def equipment_card
    if language==:en
      bs2098_old_equipment
      x=@object;actions=[]
      ids=x.features.select { |f| f.code==43 }.map { |f| f.data_id }
      x.note.scan(/<攻撃ID変更[:：](\d+)>/).each { |m| ids<<m[0].to_i }
      ids.uniq.each do |id|
        skill=$data_skills[id];next unless skill
        actions<<name(skill)
        actions<<'  Per hit: '+skill.damage.formula.to_s.strip unless skill.damage.none?
        actions+=note_rules(skill).map { |s| '  '+s }
      end
      add('Skills / attack',actions)
      return
    end
    x=@object;return bs2098_old_equipment unless reference098.get(x)
    rows=ref_lines(x,'Brief')
    rows=[reference098.brief(x)] if rows.empty?
    rows+=ref_facts(x).select { |a,b| a=='Bonuses' }.map { |a,b| a+': '+b }
    add(t('Equipment','Equipment'),rows)
    add(t('Properties','Properties'),ref_lines(x,'Properties'))
    special=note_rules(x)
    # These reviewed explanations are not represented by database traits:
    # story purposes, storage restrictions and exact revival semantics.
    special+=equipment_notes(x).select do |line|
      (x.is_a?(RPG::Armor) && [141,152].include?(x.id)) ||
        ['Cannot deposit','Cannot deposit','Auto-revival','Auto-revival',
         'After this revival triggers','After this revival'].any? { |prefix| line.start_with?(prefix) }
    end
    if x.features.any? { |f| f.code==61 }
      special<<'Additional slots are determined when the queue is created. Switching weapons does not add slots to an existing turn.'
    end
    if x.features.any? { |f| f.code==34 && f.value>0 }
      special<<'Extra normal attack repeats require the selected ID to match the current weapon\'s normal attack. Another technique does not become a combo.'
    end
    x.note.scan(/<戦闘前ステート付与[:：](\d+)(?:,(\d+))?>/).each do |id,chance|
      state=$data_states[id.to_i];next unless state
      special<<'Initial state '+name(state)+':';special+=state_lines(state)
    end
    # Special normal attacks have their own formulas/repeats. The complete action
    # definition belongs here even when it is never learnable as a player skill.
    ids=x.features.select { |f| f.code==43 }.map { |f| f.data_id }
    x.note.scan(/<攻撃ID変更[:：](\d+)>/).each { |m| ids<<m[0].to_i }
    actions=[]
    ids.uniq.each do |id|
      skill=$data_skills[id];next unless skill
      actions<<name(skill)+': '+reference098.brief(skill).to_s
      actions<<'  Per hit: '+skill.damage.formula.to_s.strip unless skill.damage.none?
      actions+=note_rules(skill).map { |s| '  '+s }
    end
    add(t('Special','Special'),special)
    add(t('Skills / attack','Skills / attack'),actions)
    if x.is_a?(RPG::Weapon) && BS2Suite.enabled?('semantic_groups')
      add(t('Weapon shelves','Weapon shelves'),['Number in N — equip now. D on an N row — final action; N N clears the assignment.',
        'D in equipment weapon selection or Items → Weapons assigns a separate starting weapon.',
        'Selected attack ID is retained when switching weapons; stats, costs and extra shots depend on current equipment.'])
    end
  end
end
